9: // Description: Internal stuff for DevIL (IL, ILU and ILUT)
10: //
11: //-----------------------------------------------------------------------------
12: 
13: #ifndef IL_EXPORTS_H
14: #define IL_EXPORTS_H
15: 
16: #include "IL/il.h"
17: 
18: #ifdef DEBUG
19: 	#include <assert.h>
20: #else
21: 	#define assert(x)
22: #endif
23: 
24: 
25: #ifdef NOINLINE
26:     // No inlining. Treat all inline funcs as static.
27:     // Functions will be replicated in all translation units
28:     // use them.
29:     #define STATIC_INLINE static
30: #else
31:     #if defined(_MSC_VER) && !defined(__cplusplus)
32:         // MSVC compiler uses __inline when compiling C (not C++)
33:         #define STATIC_INLINE static __inline
34:     #else
